'use strict';

// MODULES //

var tape = require( 'tape' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var bytesPerElement = require( '@stdlib/ndarray/base/bytes-per-element' );
var factory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an unsupported data type', function test( t ) {
	var values;
	var i;

	values = [
		'float',
		'double',
		'int8',
		'uint8',
		'generic',
		null,
		void 0,
		NaN,
		5,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided value: ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			factory( value );
		};
	}
});

tape( 'the function returns a typed array constructor having expected static properties', function test( t ) {
	var expected;
	var dtypes;
	var ctor;
	var i;

	dtypes = [
		'float64',
		'float32',
		'int32',
		'int16',
		'uint32',
		'uint16'
	];
	expected = [
		'Float64ArrayFE',
		'Float32ArrayFE',
		'Int32ArrayFE',
		'Int16ArrayFE',
		'Uint32ArrayFE',
		'Uint16ArrayFE'
	];
	for ( i = 0; i < dtypes.length; i++ ) {
		ctor = factory( dtypes[ i ] );
		t.strictEqual( typeof ctor, 'function', 'returns a constructor for data type: ' + dtypes[ i ] );
		t.strictEqual( ctor.name, expected[ i ], 'returns a constructor having expected name for data type: ' + dtypes[ i ] );
		t.strictEqual( ctor.BYTES_PER_ELEMENT, bytesPerElement( dtypes[ i ] ), 'returns a constructor having expected bytes per element for data type: ' + dtypes[ i ] );
	}
	t.end();
});

tape( 'constructor throws an error if provided an unsupported byte order', function test( t ) {
	var Float64ArrayFE;
	var values;
	var i;

	Float64ArrayFE = factory( 'float64' );
	values = [
		'',
		'little',
		'big',
		'be',
		'le',
		5,
		null,
		void 0,
		{}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided value: ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return new Float64ArrayFE( value );
		};
	}
});

tape( 'constructor accepts case-insensitive byte order strings', function test( t ) {
	var Float64ArrayFE;
	var arr;

	Float64ArrayFE = factory( 'float64' );
	arr = new Float64ArrayFE( 'LITTLE-ENDIAN', [ 1.0, 2.0 ] );

	t.strictEqual( arr.length, 2, 'returns expected length' );
	t.strictEqual( arr.get( 0 ), 1.0, 'returns expected first element' );
	t.strictEqual( arr.get( 1 ), 2.0, 'returns expected second element' );
	t.end();
});

tape( 'constructor supports length, array-like object, and ArrayBuffer initialization', function test( t ) {
	var Float64ArrayFE;
	var arr3;
	var arr2;
	var arr1;
	var buf;

	Float64ArrayFE = factory( 'float64' );

	arr1 = new Float64ArrayFE( 'little-endian', 3 );
	t.strictEqual( arr1.length, 3, 'returns expected length for length initialization' );
	t.strictEqual( arr1.byteLength, 24, 'returns expected byte length for length initialization' );

	arr2 = new Float64ArrayFE( 'little-endian', [ 1.0, 2.0, 3.0 ] );
	t.strictEqual( arr2.length, 3, 'returns expected length for array-like initialization' );
	t.strictEqual( arr2.get( 0 ), 1.0, 'returns expected first element for array-like initialization' );
	t.strictEqual( arr2.get( 2 ), 3.0, 'returns expected last element for array-like initialization' );

	buf = new ArrayBuffer( 32 );
	arr3 = new Float64ArrayFE( 'little-endian', buf, 8, 2 );
	t.strictEqual( arr3.length, 2, 'returns expected length for buffer initialization' );
	t.strictEqual( arr3.byteOffset, 8, 'returns expected byte offset for buffer initialization' );
	t.strictEqual( arr3.byteLength, 16, 'returns expected byte length for buffer initialization' );
	t.end();
});

tape( 'constructor throws a range error if an ArrayBuffer byte length is not a multiple of data type size', function test( t ) {
	var Uint16ArrayFE;

	Uint16ArrayFE = factory( 'uint16' );
	t.throws( badValue, RangeError, 'throws expected error' );
	t.end();

	function badValue() {
		return new Uint16ArrayFE( 'little-endian', new ArrayBuffer( 3 ) );
	}
});

tape( 'typed arrays created for different byte orders interpret shared bytes differently', function test( t ) {
	var Uint16ArrayFE;
	var arrBE;
	var arrLE;
	var buf;

	Uint16ArrayFE = factory( 'uint16' );
	buf = new ArrayBuffer( 2 );

	arrLE = new Uint16ArrayFE( 'little-endian', buf );
	arrBE = new Uint16ArrayFE( 'big-endian', buf );

	arrLE.set( 258, 0 );
	t.strictEqual( arrLE.get( 0 ), 258, 'little-endian view returns expected value' );
	t.strictEqual( arrBE.get( 0 ), 513, 'big-endian view returns expected value from same bytes' );
	t.end();
});

tape( 'each constructor has working `from` and `of` static methods', function test( t ) {
	var Float64ArrayFE;
	var arr2;
	var arr1;

	Float64ArrayFE = factory( 'float64' );

	arr1 = Float64ArrayFE.from( 'big-endian', [ 1.0, 2.0 ], function map( v ) {
		return v * 2.0;
	});
	t.strictEqual( arr1.length, 2, 'returns expected length for `from`' );
	t.strictEqual( arr1.get( 0 ), 2.0, 'returns expected first element for `from`' );
	t.strictEqual( arr1.get( 1 ), 4.0, 'returns expected second element for `from`' );

	arr2 = Float64ArrayFE.of( 'little-endian', 3.0, 4.0, 5.0 );
	t.strictEqual( arr2.length, 3, 'returns expected length for `of`' );
	t.strictEqual( arr2.get( 0 ), 3.0, 'returns expected first element for `of`' );
	t.strictEqual( arr2.get( 2 ), 5.0, 'returns expected last element for `of`' );
	t.end();
});
